css:
.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; orientation: Landscape; page-size: A4; }
.print-format { padding: 0 !important; width: 297mm !important; max-width: 297mm !important; min-height: 0 !important; font-family: Hind, "Segoe UI", Arial, sans-serif; }
.cert { width: 297mm; height: 209mm; padding: 6mm; box-sizing: border-box; background: #fff; page-break-inside: avoid; overflow: hidden; }
.cert .inner { position: relative; height: 197mm; border: 2mm solid #234165; outline: 0; box-sizing: border-box; text-align: center; padding: 8mm 18mm 0; }
.cert .inner:before { content: ""; position: absolute; top: 3mm; left: 3mm; right: 3mm; bottom: 3mm; border: 0.4mm solid #E44B47; }
.cert .dot { position: absolute; width: 3.4mm; height: 3.4mm; border-radius: 50%; background: #E44B47; }
.cert .tl { top: 1.3mm; left: 1.3mm; } .cert .tr { top: 1.3mm; right: 1.3mm; }
.cert .bl { bottom: 1.3mm; left: 1.3mm; } .cert .br { bottom: 1.3mm; right: 1.3mm; }
.cert .logo { height: 22mm; margin-top: 2mm; }
.cert .issuer { font: 500 8.5pt "IBM Plex Mono", Consolas, monospace; letter-spacing: 1.6pt; color: #6B7380; margin-top: 3mm; }
.cert .title { font-size: 30pt; font-weight: 700; color: #234165; margin-top: 5mm; line-height: 1.1; }
.cert .bar { width: 22mm; height: 1mm; background: #E44B47; margin: 3mm auto 0; }
.cert .lead { font-size: 12pt; color: #6B7380; margin-top: 6mm; }
.cert .name { font-size: 34pt; font-weight: 700; color: #234165; margin-top: 2mm; line-height: 1.15; }
.cert .rule { width: 165mm; border-top: 0.4mm solid rgba(38, 44, 92, .35); margin: 2mm auto 0; }
.cert .ident { font: 500 10pt "IBM Plex Mono", Consolas, monospace; color: #6B7380; margin-top: 3mm; }
.cert .body { font-size: 12.5pt; color: #2B3440; margin-top: 6mm; line-height: 1.55; }
.cert .score { font-size: 12.5pt; font-weight: 600; color: #2B3440; margin-top: 2mm; }
.cert .no { font: 500 10pt "IBM Plex Mono", Consolas, monospace; color: #E44B47; margin-top: 4mm; }
.cert table.sign { width: 100%; margin-top: 9mm; border-collapse: collapse; }
.cert table.sign td { width: 33.3%; padding: 0 8mm; text-align: center; vertical-align: bottom; border: 0; }
.cert table.sign .v { font-size: 13pt; font-weight: 700; color: #234165; border-bottom: 0.4mm solid #2B3440; padding-bottom: 2mm; }
.cert table.sign .l { font-size: 10pt; color: #6B7380; margin-top: 2mm; }
.cert .foot { position: absolute; left: 0; right: 0; bottom: 7mm; font-size: 8.5pt; color: #6B7380; }
.cert .void { position: absolute; top: 80mm; left: 0; right: 0; font-size: 70pt; font-weight: 700; color: rgba(194, 53, 49, .16); -webkit-transform: rotate(-18deg); transform: rotate(-18deg); }
